local INI_C = {["Grampo_0"]={0.95,0.5,0.1},["Grampo_1"]={0.95,0.5,0.1},["Grampo_2"]={0.95,0.5,0.1},["Grampo_3"]={0.95,0.5,0.1},["Torre_Sinal_Amarelo"]={0.18,0.18,0.18},["Torre_Sinal_Verde"]={0.1,0.9,0.2},["Torre_Sinal_Vermelho"]={0.18,0.18,0.18}}

-- reproducao da animacao gravada (compativel com CoppeliaSim 4.0 / 4.1)
local H = {}
local juntas = {}
local flange, quadro, peca, fresa, cola
local fresaM, colaM
local ui = nil
local evIdx = 1
local ultimoT = -1

local function h(nome)
    if H[nome] == nil then
        local ok, r = pcall(sim.getObjectHandle, nome)
        H[nome] = ok and r or -1
    end
    return H[nome]
end

local function visivel(nome, v)
    local o = h(nome)
    if o ~= -1 then sim.setObjectInt32Parameter(o, sim.objintparam_visibility_layer, v) end
end

local function cor(nome, rgb)
    local o = h(nome)
    if o ~= -1 then sim.setShapeColor(o, nil, sim.colorcomponent_ambient_diffuse, rgb) end
end

local function texto(id, txt)
    if ui then
        pcall(simUI.setLabelText, ui, tonumber(id), txt)
    elseif tonumber(id) == 1 then
        local limpo = string.gsub(txt, '<[^>]*>', '')
        sim.addStatusbarMessage(limpo)
    end
end

local function aplicarEvento(e)
    local tipo, alvo, val = e[2], e[3], e[4]
    if tipo == 'V' then
        visivel(alvo, tonumber(val))
    elseif tipo == 'C' then
        local r, g, b = string.match(val, '([^,]+),([^,]+),([^,]+)')
        cor(alvo, {tonumber(r), tonumber(g), tonumber(b)})
    elseif tipo == 'U' then
        texto(alvo, val)
    end
end

local function reiniciar()
    for nome, v in pairs(INI_V) do visivel(nome, v) end
    for nome, c in pairs(INI_C) do cor(nome, c) end
    evIdx = 1
end

function sysCall_init()
    for i = 1, 6 do juntas[i] = sim.getObjectHandle('UR10_joint' .. i) end
    flange = sim.getObjectHandle('UR10_link7')
    quadro = sim.getObjectHandle('Gabarito_Quadro')
    peca = sim.getObjectHandle('Painel')
    fresa = sim.getObjectHandle('Ferramenta_Fresa')
    cola = sim.getObjectHandle('Ferramenta_Cola')
    fresaM = sim.getObjectMatrix(fresa, -1)
    colaM = sim.getObjectMatrix(cola, -1)
    if simUI then
        local ok, r = pcall(simUI.create, [[<ui title="Celula CP05 - painel do CLP" closeable="false" resizable="false" placement="relative" position="12,12" layout="vbox">
            <label id="1" text="" /><label id="2" text="" /><label id="3" text="" /><label id="4" text="" />
            <label id="5" text="" /><label id="6" text="" /><label id="7" text="" /></ui>]])
        if ok then ui = r end
    end
    -- cortina de luz
    local a = h('Cortina_Saida_A')
    local b = h('Cortina_Saida_B')
    if a ~= -1 and b ~= -1 then
        local d = sim.addDrawingObject(sim.drawing_lines, 2, 0, -1, 50, {1, 0.1, 0.1})
        local pa = sim.getObjectPosition(a, -1)
        local pb = sim.getObjectPosition(b, -1)
        for z = 0.25, 1.65, 0.1 do sim.addDrawingObjectItem(d, {pa[1], pa[2], z, pb[1], pb[2], z}) end
    end
    reiniciar()
end

function sysCall_actuation()
    local t = sim.getSimulationTime() % PERIODO
    if t < ultimoT then reiniciar() end
    ultimoT = t
    local i = math.floor(t / DT) + 1
    if i > #FR then i = #FR end
    local f = FR[i]
    for k = 1, 6 do sim.setJointPosition(juntas[k], f[k]) end
    sim.setObjectOrientation(quadro, -1, {f[7], 0, 0})
    sim.setObjectPosition(peca, -1, {f[8], f[9], f[10]})
    sim.setObjectOrientation(peca, -1, {f[11], f[12], f[13]})
    local fm = sim.getObjectMatrix(flange, -1)
    if f[14] == 1 then sim.setObjectMatrix(fresa, -1, fm) else sim.setObjectMatrix(fresa, -1, fresaM) end
    if f[14] == 2 then sim.setObjectMatrix(cola, -1, fm) else sim.setObjectMatrix(cola, -1, colaM) end
    while evIdx <= #EV and EV[evIdx][1] <= t do
        aplicarEvento(EV[evIdx])
        evIdx = evIdx + 1
    end
end

function sysCall_cleanup()
    if ui then pcall(simUI.destroy, ui) end
    sim.setObjectMatrix(fresa, -1, fresaM)
    sim.setObjectMatrix(cola, -1, colaM)
    sim.setObjectOrientation(quadro, -1, {0, 0, 0})
    reiniciar()
end
